package au.aumanet.app;
import java.util.*;import org.json.*;
/** Bounded snapshots; ages are local residence, never an RF measurement timestamp. */
final class GroupRadioConfiguration {
 static final String[] STATES={"idle","queued","applying","trial","reverting","failed","unsupported"};
 static JSONObject report(GatewayRadioConfigCodec.Message m,long now)throws Exception{if(m.kind!='R')throw new IllegalArgumentException();return new JSONObject().put("nodeId",m.target).put("sourceRun",m.run).put("observationId",m.challenge).put("verification","pinned-node").put("catalogVersion",1).put("role",m.station?"station":"ap").put("currentOptionId",m.current).put("persistedOptionId",m.persisted).put("actualOptionId",m.actual).put("trialTargetOptionId",m.trial).put("nodeConfigGeneration",m.generation).put("transactionId",m.transaction).put("status",STATES[m.state]).put("trialRemainingMs",m.remaining).put("associated",m.associated).put("persistenceKnown",m.persistenceKnown).put("canChangeAP",m.canChange).put("configuredTxPowerDbm",m.power).put("reportAgeMs",0).put("observedElapsedMs",now);}
 static JSONArray checked(JSONArray raw,long now,String verification)throws Exception{if(raw==null||raw.length()>2||!Arrays.asList("pinned-node","owner-relayed").contains(verification))throw new IllegalArgumentException();JSONArray out=new JSONArray();Set<String> ids=new HashSet<>(),roles=new HashSet<>();for(int i=0;i<raw.length();i++){JSONObject r=raw.getJSONObject(i);String id=text(r,"nodeId","[a-f0-9]{32}"),run=text(r,"sourceRun","[a-f0-9]{32}"),observation=text(r,"observationId","[A-F0-9]{64}"),tx=text(r,"transactionId","[a-f0-9]{32}"),role=r.getString("role"),state=r.getString("status");if(!ids.add(id)||!roles.add(role)||!Arrays.asList("ap","station").contains(role)||!Arrays.asList(STATES).contains(state)||number(r,"catalogVersion",1)!=1)throw new IllegalArgumentException();JSONObject v=new JSONObject().put("nodeId",id).put("sourceRun",run).put("observationId",observation).put("verification",verification).put("catalogVersion",1).put("role",role).put("transactionId",tx).put("status",state);for(String key:new String[]{"currentOptionId","persistedOptionId","actualOptionId","trialTargetOptionId"})v.put(key,number(r,key,23));v.put("nodeConfigGeneration",number(r,"nodeConfigGeneration",GroupNamePolicy.MAX_REVISION)).put("trialRemainingMs",number(r,"trialRemainingMs",30000)).put("reportAgeMs",number(r,"reportAgeMs",GroupNamePolicy.MAX_REVISION)).put("observedElapsedMs",now);long power=number(r,"configuredTxPowerDbm",24);if(power<1)throw new IllegalArgumentException();v.put("configuredTxPowerDbm",power);for(String key:new String[]{"associated","persistenceKnown","canChangeAP"}){if(!(r.get(key) instanceof Boolean))throw new IllegalArgumentException();v.put(key,r.getBoolean(key));}if(role.equals("station")&&(v.getBoolean("canChangeAP")||v.getInt("persistedOptionId")!=0))throw new IllegalArgumentException();out.put(v);}return out;}
 static JSONArray age(JSONArray values,long elapsed,long now)throws Exception{if(elapsed<0)return new JSONArray();JSONArray out=new JSONArray(values.toString());for(int i=0;i<out.length();i++){JSONObject v=out.getJSONObject(i);long prior=v.getLong("reportAgeMs");if(prior>GroupNamePolicy.MAX_REVISION-elapsed)return new JSONArray();v.put("reportAgeMs",prior+elapsed).put("observedElapsedMs",now);v.put("trialRemainingMs",Math.max(0,v.getLong("trialRemainingMs")-elapsed));}return out;}
 static JSONArray merge(JSONArray old,long elapsed,JSONArray raw,long now)throws Exception{JSONArray prior=age(old,elapsed,now),out=checked(raw,now,"owner-relayed");for(int i=0;i<out.length();i++){JSONObject v=out.getJSONObject(i);for(int j=0;j<prior.length();j++){JSONObject p=prior.getJSONObject(j);if(p.getString("nodeId").equals(v.getString("nodeId"))&&p.getString("sourceRun").equals(v.getString("sourceRun"))&&p.getString("observationId").equals(v.getString("observationId")))v.put("reportAgeMs",Math.max(v.getLong("reportAgeMs"),p.getLong("reportAgeMs")));}}return out;}
 private static String text(JSONObject r,String key,String pattern)throws Exception{Object v=r.get(key);if(!(v instanceof String)||!((String)v).matches(pattern))throw new IllegalArgumentException();return(String)v;}private static long number(JSONObject r,String key,long max)throws Exception{long n=GroupNameMetadata.number(r,key);if(n>max)throw new IllegalArgumentException();return n;}
 private GroupRadioConfiguration(){}
}
